async (req, res) => {
    const doFunnyNumber = true;
    await res.setHeader('serverside-force-content-length', 'true');
    // console.log('[main.all("/")]', req.socket.address());
    const sockAddr = req.socket.address();
    // @ts-expect-error
    if (!sockAddr.family || !sockAddr.address || !sockAddr.port) {
        await res.setHeader('Content-Type', 'application/json');
        await res.setStatus(HTTP_Server_1.EHTTPStatus.INTERNAL_SERVER_ERROR);
        await res.end(JSON.stringify({
            code: (0, HTTP_Server_1.status2CodeNStr)(HTTP_Server_1.EHTTPStatus.INTERNAL_SERVER_ERROR),
            error: 'Something went wrong :!'
        }));
        return;
    }
    // @ts-expect-error
    const addr_comb = `${sockAddr.family}://${sockAddr.address}:${sockAddr.port}`;
    if (!addrCount.has(addr_comb))
        addrCount.set(addr_comb, 0);
    if (addrCount.get(addr_comb) > 10) {
        let responseCode = HTTP_Server_1.EHTTPStatus.TOO_MANY_REQUESTS;
        if (doFunnyNumber === true)
            responseCode = HTTP_Server_1.EHTTPStatus.KEEP_YOUR_CALM;
        else
            responseCode = HTTP_Server_1.EHTTPStatus.TOO_MANY_REQUESTS;
        await res.setHeader('Content-Type', 'application/json');
        await res.setStatus(responseCode);
        return await res.end(JSON.stringify({
            code: (0, HTTP_Server_1.status2CodeNStr)(responseCode),
            error: 'You\'re timed-out because you are sending too many requests :!'
        }));
    }
    else {
        await res.setHeader('Content-Type', 'text/plain');
        await res.setStatus(HTTP_Server_1.EHTTPStatus.OK);
        await res.end(`Joe mama - oe na na`);
        addrCount.set(addr_comb, addrCount.get(addr_comb) + 1);
    }
}

